    assert s.create_room("a", 0) == (400, None)
    assert s.create_room("a", 51) == (400, None)
    assert s.create_room("a", True) == (400, None)
    assert s.create_room("a", 50) == (201, {"room": "a"})
    assert s.create_room("a", 5) == (409, None)
    assert s.create_room("a", 0) == (400, None)


def test_book_order_and_validation():
    s = mk()
    assert s.book("u", "nope", 5, 0, 0, 0) == (404, None)
    assert s.book("u", "r", 9, 1, 2, 1) == (400, None)
    assert s.book("u", "r", 366, 1, 2, 1) == (400, None)
    assert s.book("u", "r", 10, 5, 5, 1) == (400, None)
    assert s.book("u", "r", 10, 0, 25, 1) == (400, None)
    assert s.book("u", "r", True, 0, 1, 1) == (400, None)
    assert s.book("u", "r", 10, 0, 1, 0) == (400, None)
    assert s.book("u", "r", 10, 0, 1, 5) == (400, None)
    assert s.book("u", "r", 10, 0, 1, True) == (400, None)
    st, b = s.book("u", "r", 10, 0, 24, 4)
    assert st == 201 and b["booking_id"] == 1


def test_capacity_half_open():
    s = mk()
    assert s.book("u", "r", 20, 9, 11, 4)[0] == 201
    assert s.book("u", "r", 20, 11, 12, 4)[0] == 201
    assert s.book("u", "r", 20, 10, 11, 1)[0] == 409
    assert s.book("u", "r", 21, 10, 11, 1)[0] == 201


def test_ids_not_reused():
    s = mk()
    _, a = s.book("u", "r", 20, 1, 2, 1)
    s.cancel("u", a["booking_id"])
    _, b = s.book("u", "r", 20, 1, 2, 1)
    assert b["booking_id"] == 2


def test_cancel_rules():
    s = mk()
    _, a = s.book("u", "r", 20, 1, 2, 4)
    assert s.cancel("v", a["booking_id"]) == (404, None)
    assert s.cancel("u", 99) == (404, None)
    assert s.cancel("u", a["booking_id"]) == (200, {"status": "cancelled"})
    assert s.cancel("u", a["booking_id"]) == (409, None)
    assert s.cancel("v", a["booking_id"]) == (404, None)
    assert s.book("v", "r", 20, 1, 2, 4)[0] == 201
    assert s.list_bookings("u") == (200, [])


def test_move_rules():
    s = mk()
    _, a = s.book("u", "r", 20, 1, 3, 3)
    bid = a["booking_id"]
    s.book("w", "r", 20, 5, 7, 3)
    # overlapping own old time is fine
    st, m = s.move("u", bid, 20, 2, 4)
    assert st == 200 and m["start"] == 2 and m["end"] == 4 and m["seats"] == 3
    assert s.move("u", bid, 20, 4, 6) == (409, None)
    assert s.list_bookings("u")[1][0]["start"] == 2
    assert s.move("u", bid, 5, 1, 2) == (400, None)
    assert s.move("v", bid, 20, 1, 2) == (404, None)
    s.cancel("u", bid)
    assert s.move("u", bid, 20, 1, 2) == (409, None)
    assert s.move("u", bid, 5, 1, 2) == (409, None)


def test_list_sorted():
    s = mk(10)
    s.book("u", "r", 21, 1, 2, 1)
    s.book("u", "r", 20, 5, 6, 1)
    s.book("u", "r", 20, 5, 6, 1)
    s.book("u", "r", 20, 3, 4, 1)
    _, l = s.list_bookings("u")
    assert [(b["day"], b["start"], b["booking_id"]) for b in l] == [
        (20, 3, 4), (20, 5, 2), (20, 5, 3), (21, 1, 1)]
    assert set(l[0]) == {"booking_id", "room", "day", "start", "end", "seats"}
