    assert s.book("u", "r", 10, 5, 5, 1) == (400, None)
    assert s.book("u", "r", 10, 0, 25, 1) == (400, None)
    assert s.book("u", "r", True, 0, 1, 1) == (400, None)
    assert s.book("u", "r", 10, 0, 1, 0) == (400, None)
    assert s.book("u", "r", 10, 0, 1, 5) == (400, None)
    assert s.book("u", "r", 10, 0, 1, True) == (400, None)
