def test_move_rules():
    s = mk()
    _, a = s.book("u", "r", 20, 1, 3, 3)
    bid = a["booking_id"]
    s.book("w", "r", 20, 5, 7, 3)
    # overlapping own old time is fine
    st, m = s.move("u", bid, 20, 2, 4)
    assert st == 200 and m["start"] == 2 and m["end"] == 4 and m["seats"] == 3
    assert s.move("u", bid, 20, 4, 6) == (409, None)
    assert s.list_bookings("u")[1][0]["start"] == 2
    assert s.move("u", bid, 5, 1, 2) == (400, None)
    assert s.move("v", bid, 20, 1, 2) == (404, None)
    s.cancel("u", bid)
    assert s.move("u", bid, 20, 1, 2) == (409, None)
    assert s.move("u", bid, 5, 1, 2) == (409, None)


def test_list_sorted():
    s = mk(10)
    s.book("u", "r", 21, 1, 2, 1)
    s.book("u", "r", 20, 5, 6, 1)
    s.book("u", "r", 20, 5, 6, 1)
    s.book("u", "r", 20, 3, 4, 1)
    _, l = s.list_bookings("u")
    assert [(b["day"], b["start"], b["booking_id"]) for b in l] == [
        (20, 3, 4), (20, 5, 2), (20, 5, 3), (21, 1, 1)]
    assert set(l[0]) == {"booking_id", "room", "day", "start", "end", "seats"}
